use wow_state::Snapshot;#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum QuestTaskStage{Discover,Accept,Progress,TurnIn,Complete}pub fn stage(state:&Snapshot,quest:u32)->Option<QuestTaskStage>{if state.state.quests.completed.contains(&quest){Some(QuestTaskStage::Complete)}else{state.state.quests.active.get(&quest).map(|q|if q.complete{QuestTaskStage::TurnIn}else{QuestTaskStage::Progress})}}
